import pytest

from api_test_framework import Expect, unique_id


@pytest.mark.functional
@pytest.mark.writes
@pytest.mark.case("TC001")
@pytest.mark.priority("P0")
def test_tc001_a_booking_cancelled_one_hour_after_it_was_made_gets(api, context):
    """A booking cancelled one hour after it was made gets a full refund. Criteria: AC-1."""
    unique = unique_id()
    # 1. POST /bookings
    response = api.post("/bookings", json={
        "passenger_name": f"Ravi Kumar {unique}",
        "email": f"ravi.{unique}@testdata.example",
        "amount": 250,
        "booked_at": "2026-01-15T10:00:00Z",
    })
    Expect(response).status_is(201)
    context.remember("pnr", response.value("pnr"))
    # 2. POST /bookings/{{pnr}}/cancel
    response = api.post(f"/bookings/{context.get('pnr')}/cancel", json={"cancelled_at": "2026-01-15T11:00:00Z"})
    Expect(response).status_is(200).field_equals("refund_allowed", True).field_equals("refund_amount", 250)


